[
  {
    "title": "misaligned-half-score",
    "claim": "In Image #8, the fraction in both the HUD’s 2½ and the result’s 0 — 2½ hangs below the neighboring whole numbers.",
    "reason": "The score reads as separate vertically scattered digits.",
    "suggest": "Keep the integer and fraction in one inline row, with the fraction vertically centered beside the integer."
  },
  {
    "title": "unreadable-kick-foot",
    "claim": "In Image #13, Asmongold’s raised leg ends abruptly near the trouser cuff, and I cannot distinguish a complete foot despite the FRONT KICK label.",
    "reason": "The incomplete silhouette makes the technique harder to recognize.",
    "suggest": "Inspect that atlas cell and give the raised foot a complete, clearly visible silhouette."
  },
  {
    "title": "wrong-way-result-pose",
    "claim": "In Image #18, the winning Asmongold extends his kicking foot left while HasanAbi stands to his right.",
    "reason": "The result illustration shows the strike pointing away from the opponent.",
    "suggest": "Use a dedicated victory stance for the result screen."
  },
  {
    "title": "tiny-technique-metadata",
    "claim": "In Image #6, the technique metadata letters are roughly 10px tall when the screenshot is scaled to the stated 390px viewport.",
    "reason": "Players must read these labels to compare target height and scoring value.",
    "suggest": "Set metadata to at least 18 CSS px and wrap it beneath each move name."
  },
  {
    "title": "unexplained-result-time",
    "claim": "Image #18 shows a 29s bout clock alongside BEST 6.4S without identifying what time the record measures.",
    "reason": "A player cannot reconcile the remaining bout time with the displayed record.",
    "suggest": "Show explicitly labeled elapsed time on the result and define BEST using that same clock."
  }
]
